/**
 * Station -> robot code against RoboDK 5.9.4's own MakeProgram (tests/fixtures/robodk_gt/code/robodk_generated_code.tgz):
 * RoboDK Library stations are imported, each program is compiled (compileForPost) and post-processed with its robot's
 * post exactly like Program > Export with post processor, and every file RoboDK wrote is compared line by line
 * (tests/posts_library_util.ts: date / "generated by" lines and blank lines ignored, case-insensitive, numbers within
 * 0.011). tests/posts_gt.test.ts checks the posts on frozen events; this suite checks the event compilation too:
 *  - a call of another robot's or mechanism's program (turntable, gripper) is a call only, never moves of the caller;
 *  - no implicit frame / tool before the first move, and a frame / tool is sent only when it changes (through the
 *    program and the sub-programs generated with it);
 *  - joint targets reach the posts with pose None (UR movel(joints), ABB MoveL CalcRobT, KUKA comment, ...);
 *  - simulation events are comments holding the instruction's name; the header goes to the main program only;
 *  - RoboDK's configuration flags (Fanuc 'N'/'F'), KUKA KRC2 EXT declarations of every program called in the run.
 * Programs RoboDK regenerated from machining projects before writing the GT, and posts other fixers own the state of
 * (Motoman pulses), are not in the list.
 */
import { describe, it, expect } from 'vitest';
import { compareStationCode, haveLibrary, loadLibraryStation } from './posts_library_util';
import { ItemType } from '../src/core/items/item';
import { Program } from '../src/core/items/program';
import { Robot } from '../src/core/items/robot';
import { compileForPost, getPost } from '../src/posts/index';

const EQUAL: Array<[string, string[]]> = [
  ['Example-01.a-Robot Painting - Universal Robots.rdk', ['ApproachMove', 'MainProg', 'PaintTop', 'Retract']],
  ['Example-01.c-Robot Drilling duplicate part - KUKA.rdk', ['DrillingPart', 'DrillProgram1', 'DrillProgram2', 'GoHome', 'MainProgram']],
  ['Example-01.d-Robot Inspection 3 stations - KUKA.rdk', ['AppInspectA', 'AppInspectB', 'AppInspectC', 'GoHome', 'InspectA', 'InspectB', 'InspectC', 'MainProgram', 'MainProgramA', 'MainProgramB', 'MainProgramC', 'RetractInspectA', 'RetractInspectB', 'RetractInspectC']],
  ['Example-02.h-Robot Machining - Plastic Deburring - ABB.rdk', ['DropOut1', 'DropOut2', 'DropOut3', 'DropOut4', 'DropStation', 'GoHome', 'PickIn1', 'PickIn2', 'PickIn3', 'PickStation', 'Replace_Objects']],
  ['Example-03.h-Arc Welding - ABB.rdk', ['GoHome']],
  ['Example-03.i-Spot Welding with a KUKA robot and HMDTech weld gun.rdk', ['Main']],
  ['Example-03.j-Pump Impeller laser cutting.rdk', ['Drop', 'Drop_EarCup_1', 'Drop_EarCup_2', 'Drop_EarCup_3', 'Drop_EarCup_4', 'GoHome', 'Pick', 'Pick_EarCup_1', 'Pick_EarCup_2', 'Pick_EarCup_3', 'Pick_EarCup_4', 'Replace_Objects']],
  ['Example-05.a-Car Rim with a turntable - Kawasaki.rdk', ['MainProgram']],
  ['Example-05.b-Glazing with a turntable - ABB.rdk', ['Side270', 'Side90']],
  ['Example-05.e-Manufacturing with 2 robots.rdk', ['Home_KUKA', 'onChamfer_Start', 'onDrilling_Activate', 'onDrilling_Start', 'onPaint_Start']],
  ['Example-06.e-Conveyor with 2 UR robots.rdk', ['FeedConveyor', 'TakeConveyor']],
  ['Example-06.f-Pick and Place CNC and Dual RobotiQ Gripper-UR10.rdk', ['DropLathe', 'Drop_1', 'Drop_2', 'Drop_3', 'Drop_4', 'GoHome', 'Gripper1PickInput', 'Gripper2DropOutput', 'LathePickTransition', 'PickLathe', 'PickLatheTransition', 'Pick_3', 'Pick_4', 'ReplaceObjects', 'Work_1', 'Work_2', 'Work_3', 'Work_4']],
];

describe('station -> code equals RoboDK MakeProgram (Library stations)', () => {
  for (const [file, progs] of EQUAL) {
    it.skipIf(!haveLibrary(file))(`${file}: ${progs.length} programs`, async () => {
      const rows = await compareStationCode(file, progs);
      const bad = rows.filter((r) => r.status !== 'equal' && r.status !== 'skipped');
      expect(bad.map((r) => `${r.program}/${r.file}: ${r.status} ${r.detail ?? ''}`)).toEqual([]);
      expect(rows.filter((r) => r.status === 'equal').length).toBeGreaterThanOrEqual(progs.length);
    }, 300000);
  }
});

describe('programs of other robots and mechanisms are called, never posted as moves of the caller', () => {
  const B = 'Example-05.b-Glazing with a turntable - ABB.rdk';
  it.skipIf(!haveLibrary(B))('05.b Inside1 (IRB 2600) only calls TT0deg, the 1-axis turntable program', async () => {
    const st = await loadLibraryStation(B);
    const p = st.itemsOfType<Program>(ItemType.PROGRAM).find((x) => x.name === 'Inside1')!;
    const tt = st.itemsOfType<Program>(ItemType.PROGRAM).find((x) => x.name === 'TT0deg')!;
    expect(tt.robot()).not.toBe(p.robot());
    const compiled = compileForPost(st, p);
    expect(compiled.subprograms.map((s) => s.name)).not.toContain('TT0deg');
    const mod = getPost((p.robot() as Robot).postProcessor)!.generate(compiled).map((f) => f.content).join('\n');
    expect(mod).not.toMatch(/PROC TT0deg/);
    expect(mod).toMatch(/^\s*TT0deg;\s*$/m);
    // the arm never drives to the turntable's all-zero joint vector
    expect(mod).not.toMatch(/MoveAbsJ \[\[0\.000000,0\.000000,0\.000000,0\.000000,0\.000000,0\.000000\]/);
  }, 120000);
  const F = 'Example-06.f-Pick and Place CNC and Dual RobotiQ Gripper-UR10.rdk';
  it.skipIf(!haveLibrary(F))('06.f Drop 1 (UR10e) calls OpenGripper2 of the RobotiQ gripper without defining it as UR moves', async () => {
    const st = await loadLibraryStation(F);
    const p = st.itemsOfType<Program>(ItemType.PROGRAM).find((x) => x.name === 'Drop 1')!;
    const script = getPost((p.robot() as Robot).postProcessor)!.generate(compileForPost(st, p)).find((f) => f.name.endsWith('.script'))!.content;
    expect(script).not.toMatch(/def OpenGripper2\(\)/);
    expect(script).toMatch(/^\s*OpenGripper2\(\)\s*$/m);
    expect(script).not.toMatch(/movej\(\[0\.872665, 0\.000000, 0\.000000/);
  }, 120000);
});
